import{_ as r,o,c as a,a2 as l}from"./chunks/framework.A5mep7Fe.js";const A=JSON.parse('{"title":"🗣️ 04 · STAR 面试稿（项目经历话术）","description":"","frontmatter":{},"headers":[],"relativePath":"09-面试实战/04-STAR面试稿.md","filePath":"09-面试实战/04-STAR面试稿.md","lastUpdated":1786806808000}'),i={name:"09-面试实战/04-STAR面试稿.md"};function e(s,t,n,d,g,c){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="🗣️-04-·-star-面试稿-项目经历话术" tabindex="-1">🗣️ 04 · STAR 面试稿（项目经历话术） <a class="header-anchor" href="#🗣️-04-·-star-面试稿-项目经历话术" aria-label="Permalink to &quot;🗣️ 04 · STAR 面试稿（项目经历话术）&quot;">​</a></h1><blockquote><p>把你的项目变成「面试官想听的故事」。STAR = Situation（情境）/ Task（任务）/ Action（行动）/ Result（结果）。本篇给模板 + 可直接练的稿子。</p></blockquote><hr><h2 id="一、star-结构" tabindex="-1">一、STAR 结构 <a class="header-anchor" href="#一、star-结构" aria-label="Permalink to &quot;一、STAR 结构&quot;">​</a></h2><ul><li><strong>S（情境）</strong>：背景、问题、约束（1-2 句）</li><li><strong>T（任务）</strong>：你要解决的具体目标</li><li><strong>A（行动）</strong>：你<strong>个人</strong>做了什么（突出技术决策与权衡，避免「我们」）</li><li><strong>R（结果）</strong>：量化结果 + 你的收获（最好带数字）</li></ul><p>⚠️ 关键：A 必须突出「我」，而非团队；R 必须有数字或可比指标。</p><hr><h2 id="二、范例稿-ai-应用开发方向" tabindex="-1">二、范例稿（AI 应用开发方向） <a class="header-anchor" href="#二、范例稿-ai-应用开发方向" aria-label="Permalink to &quot;二、范例稿（AI 应用开发方向）&quot;">​</a></h2><p><strong>项目：企业智能知识库问答系统（RAG）</strong></p><ul><li><strong>S</strong>：公司 5 万员工的制度/文档分散在多个系统，人工查答慢、口径不一。</li><li><strong>T</strong>：搭建一个能基于内部文档准确问答的助手，准确率要可信、可溯源。</li><li><strong>A</strong>：我主导架构设计——用 Milvus + BM25 做混合检索，加 Cross-Encoder 重排；用 LlamaIndex 编排 RAG 流水线；引入「仅基于片段 + 给出处」约束降低幻觉；做语义缓存降本；用 RAGAS 建评测集做回归。</li><li><strong>R</strong>：召回率 0.62→0.89，答案忠实度提升 23%，P99 延迟 1.2s，月均节省人工查答约 3000 小时；我也沉淀了一套可复用的 RAG 评测流程。</li></ul><p><strong>可能的追问与应对</strong>：</p><ul><li>「为什么用混合检索？」→ 向量弱精确词、BM25 补，融合提升召回（见 <code>08-02</code>）</li><li>「幻觉怎么治？」→ 仅基于片段 + 出处 + 拒答 + 评测（见 <code>03-Agent/02-RAG</code>）</li><li>「成本怎么控？」→ 语义缓存 + 小模型路由（见 <code>08-04</code>）</li></ul><hr><h2 id="三、范例稿-算法岗方向" tabindex="-1">三、范例稿（算法岗方向） <a class="header-anchor" href="#三、范例稿-算法岗方向" aria-label="Permalink to &quot;三、范例稿（算法岗方向）&quot;">​</a></h2><p><strong>项目：垂直领域大模型微调</strong></p><ul><li><strong>S</strong>：通用模型在金融术语/合规口径上不准，且数据敏感不能出域。</li><li><strong>T</strong>：在私有环境微调一个领域模型，兼顾效果与合规。</li><li><strong>A</strong>：我设计数据管线（清洗/去重/配比），用 QLoRA 在单卡微调（省资源），做 SFT + DPO 对齐，用领域评测集做回归。</li><li><strong>R</strong>：领域任务准确率提升 18%，训练成本降 70%（QLoRA），通过私有化部署满足合规；产出一份数据配方文档被团队复用。</li></ul><hr><h2 id="四、练习方法" tabindex="-1">四、练习方法 <a class="header-anchor" href="#四、练习方法" aria-label="Permalink to &quot;四、练习方法&quot;">​</a></h2><ol><li>选 2-3 个项目，各写一版 STAR 稿（见上模板）</li><li>大声朗读练习，控制 2-3 分钟讲完</li><li>预演 10 个「为什么/怎么做/如果重来」追问</li><li>用「第一性原理 + 权衡」升华每个技术选择</li></ol><hr><p>➡️ 下一步：<a href="./05-薪资谈判与Offer选择">05-薪资谈判与Offer选择</a></p>',21)])])}const u=r(i,[["render",e]]);export{A as __pageData,u as default};
